interface M {  
    class A {  
        void display() {  
            System.out.println("Class inside interface");  
        }  
    }  
}  

public class TestClassInInterface {  
    public static void main(String[] args) {  
        // Access the nested class using the interface name
        M.A obj = new M.A();  
